+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package promql
+
+import (
+	"cmp"
+	"math/big"
+	"net/netip"
+	"slices"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+
+	"github.com/grafana/regexp"
+)
+
+type labelClass int
+
+const (
+	labelWhitespace labelClass = iota
+	labelPositiveInfinity
+	labelNumber
+	labelNegativeInfinity
+	labelDuration
+	labelBytes
+	labelVersion
+	labelIP
+	labelCIDR
+	labelTimestamp
+	labelString
+)
+
+const labelDecimalPattern = `[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?`
+
+var (
+	labelNumberRE      = regexp.MustCompile(`^` + labelDecimalPattern + `$`)
+	labelDurationRE    = regexp.MustCompile(`^(` + labelDecimalPattern + `)(ns|us|µs|μs|ms|s|m|h|d|w|y)`)
+	labelBytesRE       = regexp.MustCompile(`^(` + labelDecimalPattern + `)(B|[kKMGTPEZY]i?B)$`)
+	labelVersionRE     = regexp.MustCompile(`^v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$`)
+	labelTimestampRE   = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])$`)
+	labelDurationUnits = map[string]int64{
+		"ns": 1, "us": 1000, "µs": 1000, "μs": 1000, "ms": 1000000,
+		"s": 1000000000, "m": 60 * 1000000000, "h": 3600 * 1000000000,
+		"d": 86400 * 1000000000, "w": 7 * 86400 * 1000000000, "y": 365 * 86400 * 1000000000,
+	}
+)
+
+// A magnitude is a sum of exact decimal terms. Keeping the exponent separate
+// avoids both floating-point rounding and expanding enormous scientific values.
+type labelDecimal struct {
+	coefficient *big.Int
+	exponent    *big.Int
+}
+
+type labelMagnitude []labelDecimal
+
+func parseLabelDecimal(s string) labelDecimal {
+	exponent := new(big.Int)
+	if i := strings.IndexAny(s, "eE"); i >= 0 {
+		exponent.SetString(s[i+1:], 10)
+		s = s[:i]
+	}
+	if i := strings.IndexByte(s, '.'); i >= 0 {
+		exponent.Sub(exponent, big.NewInt(int64(len(s)-i-1)))
+		s = s[:i] + s[i+1:]
+	}
+	coefficient, _ := new(big.Int).SetString(s, 10)
+	return labelDecimal{coefficient, exponent}
+}
+
+func (a labelMagnitude) compare(b labelMagnitude) int {
+	terms := make(labelMagnitude, 0, len(a)+len(b))
+	terms = append(terms, a...)
+	for _, term := range b {
+		terms = append(terms, labelDecimal{new(big.Int).Neg(term.coefficient), term.exponent})
+	}
+	slices.SortFunc(terms, func(a, b labelDecimal) int { return a.exponent.Cmp(b.exponent) })
+	accumulator := new(big.Int)
+	remainderSign := 0
+	for i, term := range terms {
+		if i > 0 {
+			gap := new(big.Int).Sub(term.exponent, terms[i-1].exponent)
+			if gap.Sign() > 0 && accumulator.Sign() != 0 {
+				// Carry only the digits that reach the next exponent. Lower digits
+				// cannot outweigh a nonzero digit at a higher position.
+				digits := int64(len(new(big.Int).Abs(accumulator).String()))
+				if gap.Cmp(big.NewInt(digits)) >= 0 {
+					remainderSign = accumulator.Sign()
+					accumulator.SetInt64(0)
+				} else {
+					divisor := new(big.Int).Exp(big.NewInt(10), gap, nil)
+					remainder := new(big.Int)
+					accumulator.QuoRem(accumulator, divisor, remainder)
+					if remainder.Sign() != 0 {
+						remainderSign = remainder.Sign()
+					}
+				}
+			}
+		}
+		accumulator.Add(accumulator, term.coefficient)
+	}
+	if accumulator.Sign() != 0 {
+		return accumulator.Sign()
+	}
+	return remainderSign
+}
+
+type parsedLabel struct {
+	class      labelClass
+	magnitude  labelMagnitude
+	version    []string
+	address    netip.Addr
+	prefixBits int
+	timestamp  time.Time
+	fraction   string
+}
+
+func parseLabelValue(s string) parsedLabel {
+	r, _ := utf8.DecodeRuneInString(s)
+	if unicode.IsSpace(r) {
+		return parsedLabel{class: labelWhitespace}
+	}
+	switch strings.ToLower(s) {
+	case "inf", "+inf", "infinity", "+infinity":
+		return parsedLabel{class: labelPositiveInfinity}
+	case "-inf", "-infinity":
+		return parsedLabel{class: labelNegativeInfinity}
+	}
+	if labelNumberRE.MatchString(s) {
+		return parsedLabel{class: labelNumber, magnitude: labelMagnitude{parseLabelDecimal(s)}}
+	}
+	if magnitude, ok := parseLabelDuration(s); ok {
+		return parsedLabel{class: labelDuration, magnitude: magnitude}
+	}
+	if parts := labelBytesRE.FindStringSubmatch(s); parts != nil {
+		term := parseLabelDecimal(parts[1])
+		unit := parts[2]
+		power := strings.IndexByte("KMGTPEZY", strings.ToUpper(unit)[0]) + 1
+		base := int64(1000)
+		if strings.Contains(unit, "i") {
+			base = 1024
+		}
+		term.coefficient.Mul(term.coefficient, new(big.Int).Exp(big.NewInt(base), big.NewInt(int64(power)), nil))
+		return parsedLabel{class: labelBytes, magnitude: labelMagnitude{term}}
+	}
+	if version := labelVersionRE.FindStringSubmatch(s); version != nil {
+		valid := true
+		for _, part := range strings.Split(version[4], ".") {
+			if len(part) > 1 && part[0] == '0' && labelDigits(part) {
+				valid = false
+			}
+		}
+		if valid {
+			return parsedLabel{class: labelVersion, version: version[1:5]}
+		}
+	}
+	if address, err := netip.ParseAddr(s); err == nil {
+		return parsedLabel{class: labelIP, address: address}
+	}
+	if prefix, err := netip.ParsePrefix(s); err == nil {
+		return parsedLabel{class: labelCIDR, address: prefix.Masked().Addr(), prefixBits: prefix.Bits()}
+	}
+	// Parse the whole timestamp for validation, then keep its fractional seconds
+	// separately because time.Time truncates precision beyond nanoseconds.
+	if timestamp, err := time.Parse(time.RFC3339Nano, s); err == nil && labelTimestampRE.MatchString(s) {
+		fraction := ""
+		if len(s) > 19 && s[19] == '.' {
+			end := 20
+			for end < len(s) && s[end] >= '0' && s[end] <= '9' {
+				end++
+			}
+			fraction = strings.TrimRight(s[20:end], "0")
+		}
+		return parsedLabel{class: labelTimestamp, timestamp: timestamp.Truncate(time.Second), fraction: fraction}
+	}
+	return parsedLabel{class: labelString}
+}
+
+func parseLabelDuration(s string) (labelMagnitude, bool) {
+	sign := int64(1)
+	if strings.HasPrefix(s, "-") {
+		sign = -1
+		s = s[1:]
+	} else {
+		s = strings.TrimPrefix(s, "+")
+	}
+	if strings.HasPrefix(s, "+") || strings.HasPrefix(s, "-") {
+		return nil, false
+	}
+	var magnitude labelMagnitude
+	for s != "" {
+		parts := labelDurationRE.FindStringSubmatch(s)
+		if parts == nil {
+			return nil, false
+		}
+		term := parseLabelDecimal(parts[1])
+		term.coefficient.Mul(term.coefficient, big.NewInt(sign*labelDurationUnits[parts[2]]))
+		magnitude = append(magnitude, term)
+		s = s[len(parts[0]):]
+	}
+	return magnitude, len(magnitude) > 0
+}
+
+func compareLabelValues(a, b string) int {
+	if a == b {
+		return 0
+	}
+	left, right := parseLabelValue(a), parseLabelValue(b)
+	if order := cmp.Compare(left.class, right.class); order != 0 {
+		return order
+	}
+	var order int
+	switch left.class {
+	case labelNumber, labelDuration, labelBytes:
+		order = left.magnitude.compare(right.magnitude)
+	case labelVersion:
+		order = compareLabelVersions(left.version, right.version)
+	case labelIP, labelCIDR:
+		// Addr.Compare preserves IPv4-mapped IPv6 addresses as IPv6.
+		order = left.address.Compare(right.address)
+		if order == 0 && left.class == labelCIDR {
+			order = cmp.Compare(left.prefixBits, right.prefixBits)
+		}
+	case labelTimestamp:
+		order = left.timestamp.Compare(right.timestamp)
+		if order == 0 {
+			order = strings.Compare(left.fraction, right.fraction)
+		}
+	}
+	if order != 0 {
+		return order
+	}
+	return compareLabelNatural(a, b)
+}
+
+func compareLabelVersions(a, b []string) int {
+	for i := range 3 {
+		if order := compareLabelDigits(a[i], b[i]); order != 0 {
+			return order
+		}
+	}
+	if a[3] == b[3] {
+		return 0
+	}
+	if a[3] == "" {
+		return 1
+	}
+	if b[3] == "" {
+		return -1
+	}
+	left, right := strings.Split(a[3], "."), strings.Split(b[3], ".")
+	for i := 0; i < min(len(left), len(right)); i++ {
+		x, y := left[i], right[i]
+		xn, yn := labelDigits(x), labelDigits(y)
+		var order int
+		switch {
+		case xn && yn:
+			order = compareLabelDigits(x, y)
+		case xn:
+			order = -1
+		case yn:
+			order = 1
+		default:
+			order = strings.Compare(x, y)
+		}
+		if order != 0 {
+			return order
+		}
+	}
+	return cmp.Compare(len(left), len(right))
+}
+
+func labelDigits(s string) bool {
+	for i := range len(s) {
+		if s[i] < '0' || s[i] > '9' {
+			return false
+		}
+	}
+	return s != ""
+}
+
+func compareLabelDigits(a, b string) int {
+	a, b = strings.TrimLeft(a, "0"), strings.TrimLeft(b, "0")
+	if order := cmp.Compare(len(a), len(b)); order != 0 {
+		return order
+	}
+	return strings.Compare(a, b)
+}
+
+// Compare digit runs without machine-integer limits. Lexical ordering resolves
+// equivalent spellings (such as x01 and x1), making the result a total order.
+func compareLabelNatural(a, b string) int {
+	originalA, originalB := a, b
+	for a != "" && b != "" {
+		an, bn := a[0] >= '0' && a[0] <= '9', b[0] >= '0' && b[0] <= '9'
+		ai, bi := 1, 1
+		for ai < len(a) && (a[ai] >= '0' && a[ai] <= '9') == an {
+			ai++
+		}
+		for bi < len(b) && (b[bi] >= '0' && b[bi] <= '9') == bn {
+			bi++
+		}
+		var order int
+		if an && bn {
+			order = compareLabelDigits(a[:ai], b[:bi])
+		} else {
+			order = strings.Compare(a[:ai], b[:bi])
+		}
+		if order != 0 {
+			return order
+		}
+		a, b = a[ai:], b[bi:]
+	}
+	if order := cmp.Compare(len(a), len(b)); order != 0 {
+		return order
+	}
+	return strings.Compare(originalA, originalB)
+}
