+
+func TestCompareLabelValues(t *testing.T) {
+	tests := map[string][]string{
+		"domains":            {" 2", " 10", "+Inf", "-100", "0", "1e3", "-Inf", "1s", "1B", "1.0.0", "1.2.3.4", "1.2.3.0/24", "2026-01-01T00:00:00Z", "", "NaN", "a2", "a10"},
+		"whitespace":         {"\t10", " 2", " 10", " NaN", " v1.0.0", "\u00a01", "\u20031", "+Inf"},
+		"numbers":            {"-1e1000", "-1000000000000000000000000000001", "-1000000000000000000000000000000", "-.5", "-1e-1000", "+0", "-0", ".0", "0", "1e-1000", "+.5", "1", "1.", "1.0", "1e0", "+2", "2e1", "1000000000000000000000000000000", "1000000000000000000000000000001", "1e1000"},
+		"durations":          {"-1e400y", "-1h30m", "-1h", "-2.5e1s", "+0s", "+1ns", "1us", "1µs", "1μs", "1ms", "1s", "1m", "+1h", "60m", "1h30m", "1e400s", "2e400s"},
+		"duration precision": {"1e100000000000000000000h", "1e100000000000000000000h1ns", "1e100000000000000000000h2ns"},
+		"bytes":              {"-1e400YiB", "-1KiB", "-1e3B", "+0B", "+1B", "1e3B", "1kB", "1KiB", "1MB", "1MiB", "1GB", "1GiB", "1TB", "1TiB", "1PB", "1PiB", "1EB", "1EiB", "1ZB", "1ZiB", "1YB", "1YiB", "1e400B", "2e400B"},
+		"versions":           {"1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.2", "1.0.0-alpha.10", "1.0.0-beta", "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0", "1.0.0+build2", "1.0.0+build10", "v1.0.0", "1.0.1", "2.0.0", "999999999999999999999999999999.0.0", "1000000000000000000000000000000.0.0"},
+		"IP":                 {"0.0.0.0", "2.0.0.1", "10.0.0.1", "255.255.255.255", "::", "::1", "::ffff:0.0.0.0", "::ffff:192.0.2.1", "2001:db8::1"},
+		"CIDR":               {"10.0.0.0/8", "10.0.0.0/16", "10.0.0.0/24", "10.0.0.1/24", "10.0.1.0/24", "255.255.255.0/24", "::/0", "::/32", "::ffff:192.0.2.0/120", "2001:db8::/32"},
+		"timestamps":         {"2026-01-01T01:00:00+02:00", "2026-01-01T00:00:00Z", "2026-01-01T01:00:00+01:00", "2026-01-01T00:00:00.0000000001Z", "2026-01-01T00:00:00.0000000002Z", "2026-01-01T00:00:00.1Z", "2026-01-02T00:00:00Z"},
+		"natural":            {"", "1e", "1e+", "1e-", "NaN", "a", "a01", "a1", "a1b", "a2", "a10", "a999999999999999999999999999999", "a1000000000000000000000000000000"},
+	}
+	var all []string
+	for name, ordered := range tests {
+		t.Run(name, func(t *testing.T) {
+			for i, a := range ordered {
+				require.Zero(t, compareLabelValues(a, a))
+				for _, b := range ordered[i+1:] {
+					require.Equal(t, -1, compareLabelValues(a, b), "%q < %q", a, b)
+					require.Equal(t, 1, compareLabelValues(b, a), "%q > %q", b, a)
+				}
+			}
+		})
+		all = append(all, ordered...)
+	}
+	// Different input permutations must produce the same total order, including
+	// equal typed values and natural digit runs with different zero padding.
+	expected := slices.Clone(all)
+	slices.SortFunc(expected, compareLabelValues)
+	rng := rand.New(rand.NewSource(1))
+	for range 20 {
+		rng.Shuffle(len(all), func(i, j int) { all[i], all[j] = all[j], all[i] })
+		slices.SortFunc(all, compareLabelValues)
+		require.Equal(t, expected, all)
+	}
+	for i, a := range expected {
+		for _, b := range expected[i:] {
+			require.LessOrEqual(t, compareLabelValues(a, b), 0, "%q <= %q", a, b)
+		}
+	}
+}
+
+func TestLabelValueClassification(t *testing.T) {
+	for _, s := range []string{"", "NaN", "nan", "+NaN", "-NaN", "1e", "1e+", "1e-", "1eB", "1es", "1.0.0-01", "01.0.0", "1.01.0", "1.0.01", "v1.0", "1.0.0-", "1.0.0+", "1.0.0-a..b", "1.0.0+a..b", "1.0.0_foo", "1.0.0-α", "--1s", "++1s", "+-1s", "1 s", "1 KB", "1iB", "1e+KB", "192.0.2.1/33", "2026-13-01T00:00:00Z", "2026-01-01T0:00:00.1Z", "2026-01-01T00:00:00+24:00", "1 "} {
+		require.Equal(t, labelString, parseLabelValue(s).class, "%q", s)
+	}
+	for _, s := range []string{" 1", "\t1s", "\n1B", "\r1.0.0", "\u00a0192.0.2.1", " 192.0.2.0/24", " 2026-01-01T00:00:00Z", " "} {
+		require.Equal(t, labelWhitespace, parseLabelValue(s).class, "%q", s)
+	}
+}
+
+func TestLabelMagnitudeComparison(t *testing.T) {
+	// Cross-check signed sums and cancellation against exact rational arithmetic.
+	rng := rand.New(rand.NewSource(2))
+	for range 1000 {
+		var magnitude labelMagnitude
+		expected := new(big.Rat)
+		for range 10 {
+			s := fmt.Sprintf("%de%d", rng.Intn(2001)-1000, rng.Intn(41)-20)
+			magnitude = append(magnitude, parseLabelDecimal(s))
+			term, ok := new(big.Rat).SetString(s)
+			require.True(t, ok)
+			expected.Add(expected, term)
+		}
+		require.Equal(t, expected.Sign(), magnitude.compare(nil))
+	}
+	for _, pair := range [][2]string{
+		{"1e999999999999999999999", "2e999999999999999999999"},
+		{"1e999999999999999999999", "1e1000000000000000000000"},
+		{"-1e1000000000000000000000", "-1e999999999999999999999"},
+		{"1e-1000000000000000000000", "1e-999999999999999999999"},
+		{"1h-60m", "1ns"},
+		{"1e100000000000000000000h-1e100000000000000000000h", "1ns"},
+	} {
+		require.Equal(t, -1, compareLabelValues(pair[0], pair[1]), "%q < %q", pair[0], pair[1])
+	}
+}
+
