+	} {
+		var magnitude labelMagnitude
+		for _, term := range terms {
+			magnitude = append(magnitude, parseLabelDecimal(term))
+		}
+		require.Zero(t, magnitude.compare(nil))
+		for _, extra := range []string{"1e-10000000000000000000000", "-1e-10000000000000000000000"} {
+			term := parseLabelDecimal(extra)
+			require.Equal(t, term.coefficient.Sign(), append(slices.Clone(magnitude), term).compare(nil))
+		}
+	}
